package oauthui

// FoundationCSS contains the shared visual foundation for browser-facing OAuth pages.
const FoundationCSS = cssBase

const PageCSS = FoundationCSS + cssAdmin + cssAccount

const cssAccount = `.account-meta{margin:24px 0;padding:16px;border:1px solid var(--line);border-radius:12px;background:#091725}.account-meta strong{display:block}.capabilities{margin:0 0 24px}.capabilities h2{margin-bottom:10px}.capability-list{display:grid;gap:9px;margin:0;padding:0;list-style:none}.capability-list li{position:relative;padding-left:24px;color:#dce6f0}.capability-list li:before{content:'✓';position:absolute;left:0;color:var(--accent);font-weight:900}.account-actions{display:grid;gap:12px}.button-link{display:block;border-radius:11px;padding:11px 16px;background:var(--accent);color:#05120f;font-weight:800;text-align:center;text-decoration:none}`

const cssBase = `:root{color-scheme:dark;--bg:#07111f;--panel:#0d1b2a;--line:#263b51;--text:#f6f8fb;--muted:#9fb0c3;--accent:#63e6be;font-family:Inter,ui-sans-serif,system-ui,sans-serif}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 15% 0,#173552 0,transparent 35rem),var(--bg);color:var(--text);line-height:1.5}button,input,select{font:inherit}.shell{width:min(1120px,calc(100% - 32px));margin:0 auto}.auth-shell{width:min(460px,calc(100% - 32px));margin:0 auto;padding:10vh 0 48px}.brand{display:flex;align-items:center;gap:12px;font-weight:750}.brand-mark{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;background:linear-gradient(135deg,var(--accent),#4dabf7);color:#061019;font-weight:900}.eyebrow{margin:0 0 6px;color:var(--accent);font-size:.75rem;font-weight:800;letter-spacing:.12em;text-transform:uppercase}h1,h2,h3,p{margin-top:0}h1{font-size:clamp(1.9rem,4vw,2.7rem);line-height:1.08}h2{font-size:1.25rem}.muted,.hint{color:var(--muted)}.hint{display:block;margin-top:7px;font-size:.82rem}.card{background:linear-gradient(180deg,#11243a,#0d1b2a);border:1px solid var(--line);border-radius:20px;box-shadow:0 24px 70px #0005}.auth-card{margin-top:24px;padding:clamp(24px,6vw,38px)}label{display:block;color:#dce6f0;font-size:.88rem;font-weight:700}.field{margin-top:18px}input,select{display:block;width:100%;margin-top:7px;border:1px solid #38516a;border-radius:11px;background:#091725;color:var(--text);padding:11px 13px;outline:none}input:focus,select:focus{border-color:var(--accent);box-shadow:0 0 0 3px #63e6be24}input[type=checkbox]{display:inline-block;width:18px;height:18px;margin:0;accent-color:var(--accent)}button{border:0;border-radius:11px;padding:11px 16px;background:var(--accent);color:#05120f;font-weight:800;cursor:pointer}button:hover{background:#96f2d7}.button-secondary{background:#20364b;color:var(--text)}.button-danger{background:#4b2631;color:#ffd8d8}.full{width:100%;margin-top:24px}.alert{margin:0 0 20px;padding:12px 14px;border:1px solid;border-radius:11px;font-size:.9rem}.alert-error{border-color:#743843;background:#351c25;color:#ffc9c9}.alert-success{border-color:#2b725f;background:#123a31;color:#b2f2dd}`

const cssAdmin = `.topbar{border-bottom:1px solid var(--line);background:#07111f}.topbar-inner{min-height:70px;display:flex;align-items:center;justify-content:space-between;gap:20px}.identity{color:var(--muted);font-size:.86rem}.page{padding:42px 0 70px}.page-heading{margin-bottom:26px}.page-heading p{margin-bottom:0}.admin-grid{display:grid;grid-template-columns:minmax(300px,.85fr) minmax(0,1.6fr);gap:24px;align-items:start}.create-card{padding:26px;position:sticky;top:24px}.form-section{margin-top:25px;padding-top:23px;border-top:1px solid var(--line)}.user-list{display:grid;gap:13px}.user-card{border:1px solid var(--line);border-radius:16px;background:var(--panel);overflow:hidden}.user-summary{padding:18px 20px}.user-email{margin:0 0 4px;font-size:1rem}.badges{display:flex;gap:7px;flex-wrap:wrap}.badge{border-radius:999px;padding:3px 9px;background:#1a3045;color:#cbd8e5;font-size:.72rem;font-weight:800;text-transform:capitalize}.badge-admin{background:#214b42;color:#b2f2dd}.badge-disabled{background:#472631;color:#ffc9c9}.badge-pending{background:#493f21;color:#ffec99}.manage{border-top:1px solid var(--line)}summary{padding:12px 20px;color:var(--muted);font-size:.84rem;font-weight:750;cursor:pointer;list-style:none}summary:after{content:+;float:right}details[open] summary:after{content:−}.manage-body{padding:4px 20px 20px}.action-block{display:grid;grid-template-columns:1fr 1fr auto;gap:12px;align-items:end;padding:17px 0;border-top:1px solid var(--line)}.action-block:first-child{border-top:0}.action-block label{font-size:.8rem}.check-field{display:flex;align-items:center;min-height:43px}.check-field label{display:flex;align-items:center;gap:8px}.signout{margin:34px 0 0;text-align:right}.signout form{display:inline}.empty{padding:28px;text-align:center;color:var(--muted)}@media(max-width:820px){.admin-grid{grid-template-columns:1fr}.create-card{position:static}.action-block{grid-template-columns:1fr}.action-block button{width:100%}.topbar-inner{align-items:flex-start;flex-direction:column;padding:15px 0}}`

const enhancedLoginPage = `<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Sign in - Agent Smith</title><link rel='stylesheet' href='/oauth/assets/app.css'></head><body><main class='auth-shell'><div class='brand'><span class='brand-mark'>AS</span><span>Agent Smith</span></div><section class='card auth-card'><p class='eyebrow'>Secure access</p><h1>Welcome back</h1><p class='muted'>Sign in to manage this Agent Smith instance.</p>{{if .Error}}<p class='alert alert-error' role='alert'>{{.Error}}</p>{{end}}<form method='post' action='/oauth/login'><input type='hidden' name='csrf' value='{{.CSRF}}'><input type='hidden' name='transaction' value='{{.Transaction}}'><label class='field'>Email address<input name='email' type='email' autocomplete='username' maxlength='320' required autofocus></label><label class='field'>Password<input name='password' type='password' autocomplete='current-password' maxlength='1024' required></label><button class='full' type='submit'>Sign in</button></form></section></main></body></html>`

const enhancedAccountPage = `<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Your account - Agent Smith</title><link rel='stylesheet' href='/oauth/assets/app.css'></head><body><main class='auth-shell'><div class='brand'><span class='brand-mark'>AS</span><span>Agent Smith</span></div><section class='card auth-card'><p class='eyebrow'>Account</p><h1>You're signed in</h1><p class='muted'>Your Agent Smith account is ready.</p><div class='account-meta'><strong>{{.User.Email}}</strong><span class='muted'>Role: {{.User.Role}}</span></div><section class='capabilities' aria-labelledby='capabilities-heading'><h2 id='capabilities-heading'>What you can do</h2><ul class='capability-list'>{{range .Capabilities}}<li>{{.}}</li>{{end}}</ul></section><div class='account-actions'><a class='button-link' href='/oauth/account/password'>Change password</a><form method='post' action='/oauth/logout'><input type='hidden' name='csrf' value='{{.CSRF}}'><button class='button-secondary full' type='submit'>Sign out</button></form></div></section></main></body></html>`

const enhancedPasswordPage = `<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Change password - Agent Smith</title><link rel='stylesheet' href='/oauth/assets/app.css'></head><body><main class='auth-shell'><div class='brand'><span class='brand-mark'>AS</span><span>Agent Smith</span></div><section class='card auth-card'><p class='eyebrow'>Account security</p><h1>Change your password</h1><p class='muted'>Signed in as {{.Email}}. Choose at least 12 characters.</p>{{if .Error}}<p class='alert alert-error' role='alert'>{{.Error}}</p>{{end}}<form method='post' action='/oauth/account/password'><input type='hidden' name='csrf' value='{{.CSRF}}'><input type='hidden' name='transaction' value='{{.Transaction}}'><label class='field'>Current password<input name='current_password' type='password' autocomplete='current-password' maxlength='1024' required autofocus></label><label class='field'>New password<input name='new_password' type='password' autocomplete='new-password' minlength='12' maxlength='1024' required></label><label class='field'>Confirm new password<input name='confirm_password' type='password' autocomplete='new-password' minlength='12' maxlength='1024' required></label><button class='full' type='submit'>Update password</button></form></section></main></body></html>`

const enhancedAdminPage = adminHead + adminUsers + adminFoot

const adminHead = `<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>User access - Agent Smith</title><link rel='stylesheet' href='/oauth/assets/app.css'></head><body><header class='topbar'><div class='shell topbar-inner'><div class='brand'><span class='brand-mark'>AS</span><span>Agent Smith</span></div><div class='identity'>Administrator - {{.Actor.Email}}</div></div></header><main class='shell page'><div class='page-heading'><p class='eyebrow'>Administration</p><h1>User access</h1><p class='muted'>Create accounts and control who can operate this instance.</p></div>{{if .Error}}<p class='alert alert-error' role='alert'>{{.Error}}</p>{{end}}{{if .Success}}<p class='alert alert-success' role='status'>{{.Success}}</p>{{end}}<div class='admin-grid'><section class='card create-card'><h2>Create a user</h2><p class='muted'>They will replace the temporary password on first sign-in.</p><form method='post' action='/oauth/admin/users/create'><input type='hidden' name='csrf' value='{{.CSRF}}'><label class='field'>User email<input name='email' type='email' autocomplete='off' maxlength='320' required></label><label class='field'>Temporary password<input name='new_password' type='password' autocomplete='new-password' minlength='12' maxlength='1024' required><span class='hint'>At least 12 characters.</span></label><label class='field'>Access role<select name='role'><option value='viewer'>Viewer - inspect only</option><option value='operator'>Operator - deploy and manage</option><option value='admin'>Admin - full access</option></select></label><div class='form-section'><h3>Confirm this change</h3><p class='hint'>Enter your own Agent Smith password for {{.Actor.Email}}, not the new user's temporary password.</p><label class='field'>Your administrator password<input name='current_password' type='password' autocomplete='current-password' maxlength='1024' required></label></div><button class='full' type='submit'>Create user</button></form></section>`

const adminUsers = `<section aria-labelledby='users-heading'><h2 id='users-heading'>People <span class='muted'>({{len .Users}})</span></h2><div class='user-list'>{{range .Users}}<article class='user-card'><div class='user-summary'><h3 class='user-email'>{{.Email}}</h3><div class='badges'><span class='badge{{if isAdmin .Role}} badge-admin{{end}}'>{{.Role}}</span>{{if not .Enabled}}<span class='badge badge-disabled'>Disabled</span>{{end}}{{if .MustChangePassword}}<span class='badge badge-pending'>Password change due</span>{{end}}</div></div><details class='manage'><summary>Manage account</summary><div class='manage-body'><form class='action-block' method='post' action='/oauth/admin/users/{{.ID}}/update'><input type='hidden' name='csrf' value='{{$.CSRF}}'><label>Role<select name='role'><option value='viewer'{{if isViewer .Role}} selected{{end}}>Viewer</option><option value='operator'{{if isOperator .Role}} selected{{end}}>Operator</option><option value='admin'{{if isAdmin .Role}} selected{{end}}>Admin</option></select></label><div class='check-field'><label><input type='checkbox' name='enabled'{{if .Enabled}} checked{{end}}> Account enabled</label></div><label>Your password<input name='current_password' type='password' autocomplete='current-password' maxlength='1024' required></label><button type='submit'>Save access</button></form><form class='action-block' method='post' action='/oauth/admin/users/{{.ID}}/reset-password'><input type='hidden' name='csrf' value='{{$.CSRF}}'><label>New temporary password<input name='new_password' type='password' autocomplete='new-password' minlength='12' maxlength='1024' required></label><label>Your password<input name='current_password' type='password' autocomplete='current-password' maxlength='1024' required></label><button class='button-secondary' type='submit'>Reset password</button></form><form class='action-block' method='post' action='/oauth/admin/users/{{.ID}}/revoke-sessions'><input type='hidden' name='csrf' value='{{$.CSRF}}'><div><strong>Revoke active sessions</strong><span class='hint'>Signs this user out everywhere.</span></div><label>Your password<input name='current_password' type='password' autocomplete='current-password' maxlength='1024' required></label><button class='button-danger' type='submit'>Revoke sessions</button></form></div></details></article>{{else}}<div class='user-card empty'>No users found.</div>{{end}}</div></section>`

const adminFoot = `</div><div class='signout'><form method='post' action='/oauth/logout'><input type='hidden' name='csrf' value='{{.CSRF}}'><button class='button-secondary' type='submit'>Sign out</button></form></div></main></body></html>`
